PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,safe_name TEXT NOT NULL UNIQUE,password_hash BLOB NOT NULL,password_salt BLOB NOT NULL,email TEXT UNIQUE,country TEXT NOT NULL DEFAULT 'XX',privileges INTEGER NOT NULL DEFAULT 3,silence_end INTEGER NOT NULL DEFAULT 0,restricted INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL DEFAULT (unixepoch()),last_login INTEGER);
CREATE TABLE IF NOT EXISTS stats (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,mode INTEGER NOT NULL,ranked_score INTEGER NOT NULL DEFAULT 0,total_score INTEGER NOT NULL DEFAULT 0,pp INTEGER NOT NULL DEFAULT 0,plays INTEGER NOT NULL DEFAULT 0,play_time INTEGER NOT NULL DEFAULT 0,accuracy REAL NOT NULL DEFAULT 0,max_combo INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,mode));
CREATE TABLE IF NOT EXISTS beatmaps (id INTEGER PRIMARY KEY,set_id INTEGER NOT NULL,md5 TEXT NOT NULL UNIQUE,artist TEXT NOT NULL,title TEXT NOT NULL,version TEXT NOT NULL,creator TEXT NOT NULL,status INTEGER NOT NULL DEFAULT 2,last_update INTEGER,total_length INTEGER NOT NULL DEFAULT 0,max_combo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS scores (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),map_md5 TEXT NOT NULL,mode INTEGER NOT NULL,mods INTEGER NOT NULL,score INTEGER NOT NULL,pp REAL NOT NULL DEFAULT 0,accuracy REAL NOT NULL,max_combo INTEGER NOT NULL,n300 INTEGER NOT NULL,n100 INTEGER NOT NULL,n50 INTEGER NOT NULL,nmiss INTEGER NOT NULL,ngeki INTEGER NOT NULL,nkatu INTEGER NOT NULL,perfect INTEGER NOT NULL,passed INTEGER NOT NULL,replay BLOB,submitted_at INTEGER NOT NULL DEFAULT (unixepoch()),checksum TEXT,UNIQUE(user_id,map_md5,mode,mods,score));
CREATE INDEX IF NOT EXISTS scores_leaderboard ON scores(map_md5,mode,mods,pp DESC,score DESC);
CREATE TABLE IF NOT EXISTS score_pins (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,score_id INTEGER NOT NULL UNIQUE REFERENCES scores(id) ON DELETE CASCADE,pinned_at INTEGER NOT NULL DEFAULT (unixepoch()),PRIMARY KEY(user_id,score_id));
CREATE INDEX IF NOT EXISTS score_pins_user_time ON score_pins(user_id,pinned_at DESC,score_id DESC);
CREATE TABLE IF NOT EXISTS friends (user_id INTEGER REFERENCES users(id),friend_id INTEGER REFERENCES users(id),PRIMARY KEY(user_id,friend_id));
CREATE TABLE IF NOT EXISTS favourites (user_id INTEGER REFERENCES users(id),set_id INTEGER NOT NULL,created_at INTEGER DEFAULT (unixepoch()),PRIMARY KEY(user_id,set_id));
CREATE TABLE IF NOT EXISTS ratings (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,map_md5 TEXT NOT NULL REFERENCES beatmaps(md5) ON UPDATE CASCADE ON DELETE CASCADE,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 10),created_at INTEGER NOT NULL DEFAULT (unixepoch()),PRIMARY KEY(user_id,map_md5));
CREATE TABLE IF NOT EXISTS beatmap_comments (id INTEGER PRIMARY KEY AUTOINCREMENT,target_id INTEGER NOT NULL,target_type TEXT NOT NULL CHECK(target_type IN ('song','map','replay')),user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,time REAL NOT NULL,comment TEXT NOT NULL CHECK(length(comment) BETWEEN 1 AND 80),colour TEXT CHECK(colour IS NULL OR length(colour)=6),created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS beatmap_comments_target ON beatmap_comments(target_type,target_id,id);
CREATE TABLE IF NOT EXISTS direct_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,from_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,to_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,message TEXT NOT NULL CHECK(length(message) BETWEEN 1 AND 2000),read INTEGER NOT NULL DEFAULT 0 CHECK(read IN (0,1)),created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS direct_messages_unread ON direct_messages(to_id,read,created_at,id);
CREATE INDEX IF NOT EXISTS direct_messages_conversation ON direct_messages(to_id,from_id,read,id);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY,actor_id INTEGER,action TEXT NOT NULL,target TEXT,detail TEXT,created_at INTEGER DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS lazer_scores (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),beatmap_id INTEGER NOT NULL,ruleset_id INTEGER NOT NULL,total_score INTEGER NOT NULL,legacy_total_score INTEGER,accuracy REAL NOT NULL,max_combo INTEGER NOT NULL,passed INTEGER NOT NULL,mods_json TEXT NOT NULL,statistics_json TEXT NOT NULL,rank_namespace TEXT NOT NULL,client_version TEXT,replay BLOB,submitted_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS lazer_scores_board ON lazer_scores(beatmap_id,ruleset_id,rank_namespace,total_score DESC);
CREATE TABLE IF NOT EXISTS lazer_score_tokens (id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,beatmap_id INTEGER NOT NULL REFERENCES beatmaps(id) ON DELETE CASCADE,beatmap_hash TEXT NOT NULL CHECK(length(beatmap_hash)=32),ruleset_id INTEGER NOT NULL CHECK(ruleset_id BETWEEN 0 AND 3),version_hash TEXT NOT NULL CHECK(length(version_hash)=32),created_at INTEGER NOT NULL DEFAULT (unixepoch()),expires_at INTEGER NOT NULL,consumed_at INTEGER,score_id INTEGER REFERENCES lazer_scores(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS lazer_score_tokens_user_expiry ON lazer_score_tokens(user_id,expires_at DESC);
CREATE TABLE IF NOT EXISTS custom_mods (acronym TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,ranked INTEGER NOT NULL DEFAULT 0,score_multiplier REAL NOT NULL DEFAULT 1.0,settings_schema TEXT NOT NULL DEFAULT '{}');
INSERT OR IGNORE INTO custom_mods(acronym,name,description,ranked,score_multiplier,settings_schema) VALUES('RX','Relax','Server-side cursor relax; clicks are generated automatically.',0,0.0,'{"type":"object","additionalProperties":false}');
CREATE TABLE IF NOT EXISTS oauth_tokens (token_hash BLOB PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,scopes TEXT NOT NULL,client_id INTEGER,created_at INTEGER NOT NULL DEFAULT (unixepoch()),expires_at INTEGER NOT NULL,revoked_at INTEGER,last_used_at INTEGER);
CREATE INDEX IF NOT EXISTS oauth_tokens_user ON oauth_tokens(user_id,expires_at);
